MM.mnemo[1] = {"cards":[{"id":"ko-k3-0004","w":"빠르다","cs":"rychlý","en":"to be fast","p":"a","o":"k","ex":"말이 너무 빨라요.","exc":"Mluví moc rychle. (이 → 1. pád; 너무 → moc)","h":"PÁ-RŮ ≈ PÁRA: parní lokomotiva se řítí rychle – 빨라요, a už je pryč.","m":"Nepravidelné časování na 르: ㅡ vypadne a přibude ㄹ → 빨라요. Plete se s 바쁘다 (zaneprázdněný); opak je 느리다 (pomalý).","tv":["빨라요"],"irr":"르"},{"id":"ko-k3-0005","w":"어렵다","cs":"těžký, obtížný","en":"to be difficult","p":"a","o":"k","ex":"한국어 너무 어려워요.","exc":"Korejština je moc těžká. (너무 → moc, příliš)","h":"O-RJO ≈ OŘECH: tvrdý ořech se louská těžko. 어려워요 = to je těžké.","m":"Nepravidelné časování na ㅂ: ㅂ se mění na 우 → 어려워요. Platí jen pro obtížnost (na fyzickou váhu je 무겁다); opak 쉽다 (snadný).","tv":["어려워요"],"irr":"ㅂ"},{"id":"ko-k3-0006","w":"쉽다","cs":"snadný, lehký","en":"to be easy","p":"a","o":"k","ex":"이거 너무 쉬워요.","exc":"Tohle je moc snadné. (너무 → moc, příliš)","h":"ŠUP: šup a je hotovo – snadné. Opak 어렵다 (tvrdý OŘECH).","m":"Nepravidelné časování na ㅂ → 쉬워요. Používá se pro snadnost úkolu (fyzicky lehký je 가볍다); opak 어렵다 (obtížný).","tv":["쉬워요"],"irr":"ㅂ"},{"id":"ko-k3-0007","w":"시끄럽다","cs":"hlučný","en":"to be noisy","p":"a","o":"k","ex":"여기 너무 시끄러워요.","exc":"Tady je moc velký hluk. (너무 → moc, příliš)","h":"ŠI-KRUP: kroupy bubnují na plechovou střechu – to je randál! 시끄러워! = Ticho!","m":"Nepravidelné časování na ㅂ → 시끄러워요. Časté spojení: 시끄러운 소리 = hlučný zvuk; opak 조용하다 (tichý).","tv":["시끄러워요"],"irr":"ㅂ"},{"id":"ko-k3-0008","w":"덥다","cs":"horký (o počasí)","en":"to be hot (weather)","p":"a","o":"k","ex":"오늘 너무 더워요.","exc":"Dneska je strašné horko. (너무 → moc, hrozně)","h":"TOP: v létě pořád někdo TOPí, je tu vedro. 더워요 = je horko.","m":"Nepravidelné časování na ㅂ → 더워요. Používá se jen pro počasí a teplotu vzduchu (na horký předmět či nápoj je 뜨겁다); opak 춥다 (chladný).","tv":["더워요"],"irr":"ㅂ"},{"id":"ko-k3-0009","w":"맵다","cs":"pálivý, ostrý","en":"to be spicy","p":"a","o":"k","ex":"라면 너무 매워요.","exc":"Ten rámen je moc pálivý. (너무 → moc, příliš)","h":"MEP ≈ „MĚ PÁLÍ!“: křičíš po lžíci kimči. 매워요 = pálí to.","m":"Nepravidelné časování na ㅂ → 매워요. Časté spojení: 매운 음식 = pálivé jídlo, 매운맛 = pálivá chuť.","tv":["매워요"],"irr":"ㅂ"},{"id":"ko-k3-0010","w":"아름답다","cs":"krásný, nádherný","en":"to be beautiful","p":"a","o":"k","ex":"너무 아름다워요.","exc":"Je to moc krásné. (너무 → moc, velmi)","h":"A-RŮM ≈ A RUM: pláž, západ slunce a rum – krásný večer.","m":"Nepravidelné časování na ㅂ → 아름다워요. Používá se hlavně pro přírodu, umění nebo atmosféru (o lidech se častěji říká 예쁘다 nebo 잘생기다).","tv":["아름다워요"],"irr":"ㅂ"},{"id":"ko-k3-0012","w":"멋있다","cs":"stylový, skvělý, fešný","en":"to be cool, stylish","p":"a","o":"k","ex":"저 모델 너무 멋있어요!","exc":"Ten model je fakt skvělý! (너무 → moc, opravdu)","h":"MOT ≈ MOTÝL: pestrý motýl je fešák, vypadá skvěle. 멋있어요!","m":"Složenina 멋 (styl, šarm) + 있다 (mít) = mít styl, výslovnost [머싣따]. Plete se s 맛있다 (chutný, od 맛 = chuť).","tv":["멋있어요"]},{"id":"ko-k3-0014","w":"졸리다","cs":"ospalý","en":"to be sleepy","p":"a","o":"k","ex":"오늘 너무 졸려요.","exc":"Dneska se mi strašně chce spát. (너무 → moc, hrozně)","h":"ČOL ≈ ČOLEK: čolek v teplé vodě usíná – je ospalý.","m":"Časuje se stažením ㅣ + 어 → 졸려요. Souvisí se slovesem 졸다 (podřimovat); podobný význam má spojení 잠이 오다 (přichází na mě spaní).","tv":["졸려요"]},{"id":"ko-k3-0015","w":"바쁘다","cs":"zaneprázdněný, mít napilno","en":"to be busy","p":"a","o":"k","ex":"오늘 너무 바빠요.","exc":"Dneska mám strašně moc práce. (너무 → moc, hrozně)","h":"PA-PÚ ≈ PAPÍRY: hromada papírů na stole – mám napilno.","m":"Samohláska ㅡ při časování mizí → 바빠요. Plete se s podobným 빠르다 (rychlý); opak je 한가하다 (mít volno).","tv":["바빠요"],"irr":"ㅡ (vypadává)"},{"id":"ko-k3-0016","w":"배고프다","cs":"hladový","en":"to be hungry","p":"a","o":"k","ex":"너무 배고파요.","exc":"Mám strašný hlad. (너무 → moc, opravdu)","h":"배 = břicho + KO-PŮ ≈ KOPE: prázdné břicho kope a kručí – mám hlad.","m":"Složenina 배 (břicho) + 고프다 (hladovět). Při časování odpadá ㅡ → 배고파요; opak je 배부르다 (sytý).","tv":["배고파요"],"irr":"ㅡ (vypadává)"},{"id":"ko-k3-0017","w":"슬프다","cs":"smutný","en":"to be sad","p":"a","o":"k","ex":"이 영화 너무 슬퍼요.","exc":"Ten film je hrozně smutný. (너무 → moc, hrozně)","h":"SŮL-PŮ ≈ SLZY: smutek, slzy a sůl na tvářích.","m":"Při časování odpadá ㅡ → 슬퍼요. Časté spojení: 슬픈 영화 = smutný film, 슬픈 노래 = smutná píseň; opak 기쁘다 (radostný).","tv":["슬퍼요"],"irr":"ㅡ (vypadává)"},{"id":"ko-k3-0018","w":"쓰다","cs":"hořký","en":"to be bitter","p":"a","o":"k","ex":"커피 너무 써요.","exc":"Ta káva je moc hořká. (너무 → moc, příliš)","h":"SSS: syčíš, když spolkneš hořký lék.","m":"Stejné slovo znamená i ‚psát‘ a ‚používat / nosit (brýle, klobouk)‘. Při časování odpadá ㅡ → 써요; opak 달다 (sladký).","tv":["써요"],"irr":"ㅡ (vypadává)"},{"id":"ko-k3-0019","w":"짜다","cs":"slaný","en":"to be salty","p":"a","o":"k","ex":"이 김밥 너무 짜요.","exc":"Tenhle kimbap je moc slaný. (너무 → moc, příliš)","h":"ČA ≈ ČABAJKA: slaná uzenina, po ní se napiješ.","m":"Časuje se stažením ㅏ + 아 → 짜요. Opak je 싱겁다 (planý, málo slaný); pozor na záměnu se slovesem 짜다 (vymačkat; sestavit plán).","tv":["짜요"]},{"id":"ko-k3-0021","w":"잘하다","cs":"umět dobře; dělat dobře, dařit se","en":"to do well, to be good at","p":"v","o":"k","ex":"석진 씨, 너무 잘했어요.","exc":"Sokdžine, udělal jste to opravdu skvěle! (너무 → moc, příliš)","h":"ČAL ≈ ČALOUNÍK: ten to umí dobře. 잘해요! = Jde ti to!","m":"Spojení příslovce 잘 (dobře) a slovesa 하다 (dělat). Když se píše dohromady (잘하다), znamená ‚být v něčem dobrý‘; opakem je 못하다 nebo 잘 못하다."},{"id":"ko-k3-0022","w":"보고 싶다","cs":"stýskat se (po někom); chtít vidět","en":"to miss (someone)","p":"f","o":"k","ex":"너무 보고 싶어요.","exc":"Moc se mi po tobě stýská. (너무 → moc, příliš)","h":"보고 = vidět + ŠIP ≈ ŠÍP: Amorův šíp – chci tě vidět, stýská se mi.","m":"Doslova ‚chtít vidět‘ (보다 + -고 싶다) – v korejštině je to běžný způsob, jak říct ‚stýská se mi po tobě‘. Osoba, po které se ti stýská, má částici 이/가 (친구가 보고 싶어요)."},{"id":"ko-k3-0023","w":"음악 소리","cs":"zvuk hudby; hudba","en":"the sound of music","p":"f","o":"m","ex":"음악 소리가 너무 커요.","exc":"Hudba je moc nahlas. (가 → 1. pád; 너무 → příliš)","h":"소리 ≈ SORRY: „Sorry, ta hudba hraje moc nahlas.“ 음악 = hudba.","m":"音 zvuk + 樂 hudba + 소리 (původní slovo pro zvuk či hlas) = zvuk hudby. Používá se, když mluvíš o hlasitosti hudby nebo o hudbě, kterou odněkud slyšíš.","r":["eum-音","ak-樂"]},{"id":"ko-k3-0024","w":"신발","cs":"boty, obuv","en":"shoes","p":"n","o":"k","ex":"신발이 너무 작아요.","exc":"Ty boty jsou moc malé. (이 → 1. pád)","h":"ŠIN-BAL: ŠINeš si to na BÁL v nových botách.","m":"신다 obout + 발 noha = to, co se obouvá na nohu. Boty se „obouvají“ slovesem 신다, zouvají 벗다."},{"id":"ko-k3-0026","w":"아직","cs":"ještě (ne); stále","en":"yet, still","p":"o","o":"k","ex":"아직 안 먹었어요.","exc":"Ještě jsem nejedl. (안 → zápor ‚ne‘)","h":"A-ČIK ≈ AČ: „Ač čekám, ještě nepřišel.“ 아직 안 왔어요.","m":"Používá se hlavně se záporem ve významu ‚ještě ne‘ (아직 안 했어요 = ještě jsem to neudělal), nebo kladně jako ‚stále ještě‘. Opakem je 벌써 (už)."},{"id":"ko-k3-0027","w":"얼른","cs":"rychle, honem; hned","en":"quickly, hurry up","p":"o","o":"k","ex":"얼른 먹어요.","exc":"Honem se najez.","h":"OL-LŮN ≈ HOLENĚ: „Honem, holeně!“","m":"Hovorové ‚rychle, honem‘, kterým někoho pobízíš, aby něco hned udělal (얼른 와! = Pojď honem!). Na rozdíl od 빨리 se hodí hlavně do výzev a přání, ne k popisu samotné rychlosti."}],"gram":{"id":"ko-k3-g01","w":"너무","en":"Too much, Very","cs":"příliš; moc, opravdu (zesílení)","vy":"Příslovce 너무 stojí přímo před přídavným jménem nebo slovesem a zesiluje jeho význam. Původně znamenalo ‚příliš, až moc‘ (často v negativním smyslu), ale v běžné hovorové korejštině se dnes běžně používá i pozitivně ve významu ‚moc, fakt, strašně‘.","m":"Univerzální zesilovač pro dobré i špatné věci: funguje jak pro stížnost (너무 비싸요 = moc drahé), tak pro nadšenou pochvalu (너무 좋아요 = moc se mi to líbí).","s":[["너무 비싸요.","Je to moc drahé."],["말이 너무 빨라요.","Mluví moc rychle."],["한국어 너무 어려워요.","Korejština je moc těžká."],["여기 너무 시끄러워요.","Tady je moc velký hluk."],["이 피자 너무 맛있어요.","Tahle pizza je fakt výborná."],["이거 너무 좋아요.","Tohle se mi moc líbí."],["석진 씨, 너무 잘했어요.","Sokdžine, povedlo se ti to skvěle."],["너무 졸려요.","Strašně se mi chce spát."],["너무 보고 싶어요.","Moc se mi po tobě stýská."],["너무 배고파요.","Mám strašný hlad."],["얼른 먹어요.","Tak honem jez."],["음악 소리가 너무 커요.","Ta hudba hraje moc nahlas."],["신발이 너무 작아요.","Ty boty jsou moc malé."],["아, 커피 너무 맛있어요.","Ach, tahle káva je fakt vynikající."],["사천팔백 원? 너무 비싸요!","Čtyři tisíce osm set wonů? To je moc drahé!"],["사장님, 여기 너무 시끄러워요.","Pane vedoucí, tady je moc velký hluk."]]}};
Object.assign(MM.mnRoots, {"eum-音":["음","音","zvuk"],"ak-樂":["악","樂","hudba"]});

